INSERT INTO changelog (title, body, created_at) VALUES ('Порядок: меню, розділи клієнта, конкуренти, радар', 'Що змінилось:
- Меню: «Робота» — Центр, Рев''ю, Задачі, Клієнти, Гроші, Реклама, Креативи; «Особисте» (згорнуте) — Стартапи, Продукти, Розвиток, Ідеї; «Знання» — Плейбуки, Журнал, Налаштування.
- Картка клієнта: розділи без даних (Продажі без CRM, Бренд, Конкуренти, Файли, Доступи, Матеріали, Плейбуки) сховані; «+ Розділ» — увімкнути потрібний (лишиться в меню клієнта). Огляд, Стратегія, Задачі, Історія, Гроші — завжди.
- Порожні графіки не малюються — замість них «Даних ще нема».
- AI-радар один — у Розвитку; у Креативах — посилання (напрямок «Креативи»).
- Конкуренти: за замовчуванням тільки «Висока загроза» і 5 колонок (решта — «Колонки»), підказка поставити топ-5 під нагляд.
- Поради від Джері за замовчуванням раз на 2 год.
- Моделі в Налаштування → Джері: 4 актуальні, старі — окремою групою «Старі моделі».', datetime('now'));
